let proofObjectUrl=null,proofPdfTask=null,pdfEnginePromise=null;
async function getPdfEngine(){if(!pdfEnginePromise)pdfEnginePromise=(async()=>{await import('./vendor/pdf.worker.mjs');return import('./vendor/pdf.mjs');})();return pdfEnginePromise;}
