function maintenanceAlerts(){const plans=db.planos_manutencao.filter(p=>maintenanceState(p).status!=='Em dia').sort((a,b)=>(maintenanceState(a).status==='Vencida'?0:1)-(maintenanceState(b).status==='Vencida'?0:1));return '<h2>Alertas de manutenção ('+plans.length+')</h2><div class="panel">'+(plans.map(maintenancePlanRow).join('')||'<div class="empty">Nenhuma manutenção próxima ou vencida.</div>')+'</div>';}
function maintenance(){const plans=newestRecords(db.planos_manutencao.filter(p=>!maintenanceFilter||p.veiculo_id===maintenanceFilter),'data_cadastro'),services=newestRecords(db.manutencoes.filter(v=>!maintenanceFilter||v.veiculo_id===maintenanceFilter));return head('Manutenção','Registrar serviço','maint:service')+`<div class="toolbar"><select class="control" data-maint-filter><option value="">Todos os veículos</option>${db.veiculos.map(c=>`<option value="${esc(c.id)}" ${c.id===maintenanceFilter?'selected':''}>${esc(maintenanceCar(c.id))}</option>`).join('')}</select>${btn('Programar manutenção periódica','maint:plan','','btn')}</div>`+cards([['Serviços registrados',services.length],['Gasto com manutenção',money(sum(services))],['Vencidas',plans.filter(p=>maintenanceState(p).status==='Vencida').length],['Próximas',plans.filter(p=>maintenanceState(p).status==='Próxima').length]])+'<h2>Programação periódica</h2><div class="panel">'+(plans.map(maintenancePlanRow).join('')||'<div class="empty">Cadastre o serviço e o intervalo recomendado para cada carro.</div>')+'</div><h2>Histórico de serviços</h2><div class="panel">'+(services.map(v=>row(v.servico+' · '+maintenanceCar(v.veiculo_id),datedEntry(v)+' · '+Number(v.km).toLocaleString('pt-BR')+' km · '+(v.oficina||'Oficina não informada'),money(v.valor),btn('Detalhes / editar','maint:service',v.id)+(v.arquivo?btn('Ver comprovante','proof:manutencoes',v.id):'')+btn('Excluir','maint:deleteservice',v.id),'Realizada')).join('')||'<div class="empty">Nenhum serviço registrado.</div>')+'</div>';}
function maintenanceForm(kind,recordId='',planId=''){if(!db.veiculos.length)return alert('Cadastre um veículo antes de lançar manutenção.');const table=kind==='plan'?'planos_manutencao':'manutencoes',x=get(table,recordId),plan=get('planos_manutencao',planId||x.plano_id),car=x.veiculo_id||plan.veiculo_id||maintenanceFilter||db.veiculos[0].id;maintenanceCurrent={kind,recordId};current=null;let fields=select('Veículo','veiculo_id',db.veiculos.map(c=>[c.id,maintenanceCar(c.id)]),car)+input('Serviço','servico','text',x.servico||plan.servico||'',true);if(kind==='plan'){fields+=input('KM da última manutenção / referência','km_base','number',x.km_base??maintenanceKm(car),true)+input('Data da última manutenção / referência','data_base','date',x.data_base||agoraLocal().data,true)+input('Intervalo em KM (opcional)','intervalo_km','number',x.intervalo_km??'')+input('Intervalo em dias (opcional)','intervalo_dias','number',x.intervalo_dias??'')+input('Avisar quando faltarem quantos KM','aviso_km','number',x.aviso_km??500)+input('Avisar quando faltarem quantos dias','aviso_dias','number',x.aviso_dias??15)+'<p class="muted field wide">Informe pelo menos um intervalo. Se usar KM e prazo, vale o que vencer primeiro. Use o intervalo recomendado para seu veículo.</p>';}else{fields+=select('Plano periódico (opcional)','plano_id',[['','Serviço avulso'],...db.planos_manutencao.filter(p=>p.veiculo_id===car).map(p=>[p.id,p.servico])],planId||x.plano_id||'')+input('Data do serviço','data','date',x.data||agoraLocal().data,true)+input('KM do carro no serviço','km','number',x.km??maintenanceKm(car),true)+input('Custo total (R$)','valor','number',x.valor??'',true)+input('Oficina','oficina','text',x.oficina||'')+proof()+(x.arquivo?`<div class="field wide">${btn('Ver comprovante','proof:manutencoes',x.id)}</div>`:'')+'<p class="muted field wide">O custo gera uma única despesa no Financeiro. Ao vincular um plano, a próxima manutenção é calculada a partir deste serviço.</p>';}
fields+=`<div class="field wide"><label>Observações</label><textarea class="control" name="observacoes" rows="3">${esc(x.observacoes||'')}</textarea></div>`;document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>${kind==='plan'?'Programar manutenção':'Registrar serviço realizado'}</h2>${btn('Fechar','close')}</div><form id="maintenance-form"><div class="grid">${fields}</div><div class="foot"><button class="btn" type="submit">Salvar</button></div></form></div></div>`;}
async function maintenanceAction(action,id){if(action==='plan'||action==='service')return maintenanceForm(action,id);if(action==='complete')return maintenanceForm('service','',id);if(action==='deleteplan'){if(confirm('Excluir a programação? O histórico dos serviços será mantido.')){db.planos_manutencao=db.planos_manutencao.filter(p=>p.id!==id);await save();}return;}if(action==='deleteservice'&&confirm('Excluir este serviço e a despesa vinculada?')){db.manutencoes=db.manutencoes.filter(v=>v.id!==id);db.despesas=db.despesas.filter(v=>v.manutencao_id!==id);await save();}}
async function submitMaintenance(form){try{const {kind,recordId}=maintenanceCurrent,table=kind==='plan'?'planos_manutencao':'manutencoes',old=get(table,recordId),v=Object.fromEntries(new FormData(form).entries());if(!get('veiculos',v.veiculo_id).id)throw Error('Selecione um veículo.');v.servico=String(v.servico||'').trim();if(!v.servico)throw Error('Informe o serviço.');const number=(key,required=false)=>{if(v[key]===''||v[key]==null){if(required)throw Error('Preencha os valores obrigatórios.');v[key]='';return;}if(!Number.isFinite(+v[key])||+v[key]<0)throw Error('Use valores válidos, iguais ou maiores que zero.');v[key]=+v[key];};if(kind==='plan'){for(const k of ['km_base','intervalo_km','intervalo_dias','aviso_km','aviso_dias','valor_km','meta_valor_km'])number(k,k==='km_base');if(!(v.intervalo_km>0||v.intervalo_dias>0))throw Error('Informe intervalo por KM ou por dias.');if(!v.data_base||!Number.isFinite(new Date(v.data_base+'T12:00:00').getTime()))throw Error('Informe uma data válida.');if(v.intervalo_dias&&!Number.isInteger(v.intervalo_dias))throw Error('O intervalo em dias deve ser inteiro.');if(recordId&&v.veiculo_id!==old.veiculo_id&&db.manutencoes.some(x=>x.plano_id===recordId))throw Error('Este plano tem serviços vinculados. Crie outro plano para trocar de veículo.');}else{number('km',true);number('valor',true);if(!v.data||!Number.isFinite(new Date(v.data+'T12:00:00').getTime()))throw Error('Informe uma data válida.');if(v.plano_id&&get('planos_manutencao',v.plano_id).veiculo_id!==v.veiculo_id)throw Error('Selecione um plano deste veículo.');const f=form.querySelector('input[type=file]')?.files[0];if(f){if(f.size>2e6||!(f.type==='application/pdf'||f.type.startsWith('image/')))throw Error('Envie imagem ou PDF de até 2 MB.');v.arquivo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});v.arquivo_nome=f.name;}}
const entry={...old,...v,...auditStamp(old),id:recordId||id()};if(recordId)Object.assign(old,entry);else db[table].push(entry);if(kind==='service'){const expense={id:'manutencao-'+entry.id,manutencao_id:entry.id,criado_em:entry.criado_em,alterado_em:entry.alterado_em,descricao:'Manutenção: '+entry.servico,veiculo_id:entry.veiculo_id,data:entry.data,valor:entry.valor,...(entry.arquivo?{arquivo:entry.arquivo,arquivo_nome:entry.arquivo_nome}:{})};const existing=db.despesas.find(x=>x.manutencao_id===entry.id);if(existing)Object.assign(existing,expense);else db.despesas.push(expense);const car=get('veiculos',entry.veiculo_id);car.km=Math.max(+car.km||0,+entry.km);}
await save();document.querySelector('#modal').innerHTML='';}catch(e){alert(e.message||'Não foi possível salvar a manutenção.');}}
document.addEventListener('change',e=>{if(e.target.matches('[data-maint-filter]')){maintenanceFilter=e.target.value;render();}if(e.target.closest('#maintenance-form')&&e.target.name==='veiculo_id'){const form=e.target.closest('form'),car=e.target.value,km=form.querySelector('[name="km"]')||form.querySelector('[name="km_base"]');if(km&&!maintenanceCurrent.recordId)km.value=maintenanceKm(car);const choices=form.querySelector('[name="plano_id"]');if(choices)choices.innerHTML='<option value="">Serviço avulso</option>'+db.planos_manutencao.filter(p=>p.veiculo_id===car).map(p=>`<option value="${esc(p.id)}">${esc(p.servico)}</option>`).join('');}if(e.target.closest('#maintenance-form')&&e.target.name==='plano_id'&&e.target.value)e.target.closest('form').querySelector('[name="servico"]').value=get('planos_manutencao',e.target.value).servico;});


let reportFilters={start:agoraLocal().data.slice(0,7)+'-01',end:agoraLocal().data,driver:'',vehicle:'',usage:''};
function reportData(){const f=reportFilters,inPeriod=d=>!!d&&d>=f.start&&d<=f.end;const trips=newestTrips(db.viagens.filter(v=>v.status==='Concluída'&&inPeriod(v.data)&&(!f.driver||v.motorista_id===f.driver)&&(!f.vehicle||v.veiculo_id===f.vehicle)&&(!f.usage||usage(v)===f.usage)));const ids=new Set(trips.map(v=>v.id));const payments=db.pagamentos.filter(p=>inPeriod(p.data)&&(!f.driver&&!f.vehicle&&!f.usage||(()=>{const t=get('viagens',p.viagem_id);return t.id&&(!f.driver||t.motorista_id===f.driver)&&(!f.vehicle||t.veiculo_id===f.vehicle)&&(!f.usage||usage(t)===f.usage);})()));const scoped=!!(f.driver||f.usage);const revenues=db.receitas.filter(r=>inPeriod(r.data)&&!scoped&&(!f.vehicle||r.veiculo_id===f.vehicle));const expenses=db.despesas.filter(r=>inPeriod(r.data)&&!scoped&&(!f.vehicle||r.veiculo_id===f.vehicle));return {trips,payments,revenues,expenses,faturado:sum(trips)+sum(revenues),recebido:sum(payments)+sum(revenues),pendente:trips.reduce((s,v)=>s+Math.max(0,(+v.valor||0)-paidTrip(v)),0),despesas:sum(expenses),km:trips.reduce((s,v)=>s+tripKm(v),0),kmReceita:trips.reduce((s,v)=>s+revenueKm(v),0),scoped};}
function reportTable(d){return `<div style="overflow:auto"><table class="report-table"><thead><tr>${['Início / conclusão','Motorista','Veículo','Trajeto','Tipo de uso','KM','Valor','Recebido¹','A receber¹','Pagamento'].map(t=>'<th>'+t+'</th>').join('')}</tr></thead><tbody>${d.trips.map(v=>`<tr><td>${esc(date(v.data))}<br>${esc(v.hora||'Não registrada')}<br><small>${esc(tripCompletionLabel(v))}<br>${esc(entryStamp(v))}</small></td><td>${esc(name('motoristas',v.motorista_id))}</td><td>${esc(tripVehicleLabel(v))}</td><td>${esc(v.origem)} → ${esc(v.destino)}</td><td>${esc(usage(v))}</td><td>${tripKm(v).toLocaleString('pt-BR')}</td><td>${esc(money(v.valor))}</td><td>${esc(money(paidTrip(v)))}</td><td>${esc(money(Math.max(0,(+v.valor||0)-paidTrip(v))))}</td><td>${esc(payStatus(v))}</td></tr>`).join('')||'<tr><td colspan="10">Nenhuma viagem concluída para estes filtros.</td></tr>'}</tbody></table></div>`;}
function reportContent(d){return cards([['Faturamento',money(d.faturado)],['Recebido no período',money(d.recebido)],['A receber das viagens¹',money(d.pendente)],['Despesas',d.scoped?'Não atribuídas':money(d.despesas)],['Saldo do período',d.scoped?'Não calculado':money(d.recebido-d.despesas)],['KM total',d.km.toLocaleString('pt-BR')+' km'],['KM com receita',d.kmReceita.toLocaleString('pt-BR')+' km'],['Faturamento por KM',money(d.kmReceita?sum(d.trips)/d.kmReceita:0)]])+`<p class="muted">Viagens ordenadas pela conclusão, da mais recente para a mais antiga. Faturamento e viagens pela data de início. Recebimentos e despesas pela data do lançamento. ¹ Recebido e saldo das viagens consideram todos os pagamentos registrados até agora, inclusive fora do período.</p>`+(d.scoped?'<p class="muted">Receitas avulsas e despesas não possuem vínculo com motorista ou tipo de uso. Por isso ficam fora deste filtro e o saldo não é calculado.</p>':'')+'<h2>Viagens concluídas ('+d.trips.length+')</h2><div class="panel">'+reportTable(d)+'</div>';}
function reports(){const f=reportFilters;const field=(label,key,type,value)=>`<div class="field"><label>${label}</label><input class="control" type="${type}" data-report-filter="${key}" value="${esc(value)}"></div>`;const choice=(label,key,values,value)=>`<div class="field"><label>${label}</label><select class="control" data-report-filter="${key}">${[['','Todos'],...values].map(([a,b])=>`<option value="${esc(a)}" ${a===value?'selected':''}>${esc(b)}</option>`).join('')}</select></div>`;return head('Relatórios')+`<div class="filters">${field('Data inicial','start','date',f.start)}${field('Data final','end','date',f.end)}${choice('Motorista','driver',db.motoristas.map(m=>[m.id,m.nome]),f.driver)}${choice('Veículo','vehicle',db.veiculos.map(c=>[c.id,maintenanceCar(c.id)]),f.vehicle)}${choice('Tipo de uso','usage',usageTypes.map(t=>[t,t]),f.usage)}</div><div class="toolbar">${btn('Imprimir / Salvar PDF','report:print','','btn')}${btn('Baixar CSV','report:csv')}</div>`+reportContent(reportData());}
function reportFilterDescription(){const f=reportFilters;return date(f.start)+' a '+date(f.end)+' · Motorista: '+(f.driver?name('motoristas',f.driver):'Todos')+' · Veículo: '+(f.vehicle?maintenanceCar(f.vehicle):'Todos')+' · Tipo de uso: '+(f.usage||'Todos');}
function printReport(){const d=reportData(),win=window.open('','_blank');if(!win)return alert('Permita a abertura da janela de impressão neste navegador.');win.document.write(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Relatório de frota</title><style>body{font:12px Arial;color:#222;margin:24px}h1{font-size:22px}h2{font-size:16px}.cards{display:flex;flex-wrap:wrap;gap:10px}.card{border:1px solid #ccc;padding:10px;min-width:150px}.card small,.card strong{display:block;margin-bottom:5px}.muted{color:#555;line-height:1.5}.report-table{width:100%;border-collapse:collapse;font-size:10px}.report-table th,.report-table td{border:1px solid #ccc;padding:6px;text-align:left;vertical-align:top}thead{display:table-header-group}tr{break-inside:avoid}@page{size:A4 landscape;margin:12mm}@media print{button{display:none}body{margin:0}}</style><h1>${esc(db.config.empresa||'Gestão de Frota')} · Relatório</h1><p>${esc(reportFilterDescription())}</p><p>Emitido em ${esc(new Date().toLocaleString('pt-BR'))}</p><button onclick="window.print()">Imprimir / Salvar PDF</button>${reportContent(d)}</html>`);win.document.close();win.focus();win.print();}
function exportReportCsv(){const d=reportData(),rows=[['RELATÓRIO DE FROTA'],[reportFilterDescription()],['Faturamento',d.faturado],['Recebido no período',d.recebido],['Saldo a receber das viagens (atual)',d.pendente],['Despesas',d.scoped?'Não atribuídas':d.despesas],['Saldo do período',d.scoped?'Não calculado':d.recebido-d.despesas],['KM total',d.km],['KM com receita',d.kmReceita],[],['Data de início','Hora de início','Data de conclusão','Hora de conclusão','Registro do lançamento','Motorista','Veículo','Origem','Destino','Tipo de uso','KM rodados','Valor da viagem','Recebido acumulado','Saldo atual','Pagamento'],...d.trips.map(v=>[date(v.data),v.hora||'',v.data_fim?date(v.data_fim):'',v.hora_fim||'',entryStamp(v),name('motoristas',v.motorista_id),tripVehicleLabel(v),v.origem||'',v.destino||'',usage(v),tripKm(v),+v.valor||0,paidTrip(v),Math.max(0,(+v.valor||0)-paidTrip(v)),payStatus(v)])];const cell=v=>{let text=typeof v==='number'?String(v).replace('.',','):String(v??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relatorio_frota_'+reportFilters.start+'_'+reportFilters.end+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('change',e=>{const key=e.target.dataset.reportFilter;if(!key)return;const value=e.target.value;if(['start','end'].includes(key)&&(!value||!Number.isFinite(new Date(value+'T12:00:00').getTime())))return alert('Informe uma data válida.');const next={...reportFilters,[key]:value};if(next.start>next.end){e.target.value=reportFilters[key];return alert('A data inicial deve ser anterior ou igual à final.');}reportFilters=next;render();});


const backupTables=['motoristas','veiculos','viagens','receitas','despesas','pagamentos','pendencias','baixas','manutencoes','planos_manutencao','metas_km'];
function validateBackup(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw)||!Array.isArray(raw.motoristas)||!Array.isArray(raw.veiculos)||!Array.isArray(raw.viagens))throw Error('Este arquivo não é um backup de gestão de frota válido.');const out=blank();for(const table of backupTables){const rows=raw[table]??[];if(!Array.isArray(rows))throw Error('Tabela inválida no backup: '+table);const ids=new Set();for(const r of rows){if(!r||typeof r!=='object'||Array.isArray(r)||typeof r.id!=='string'||!r.id||ids.has(r.id))throw Error('Registro inválido ou ID duplicado em '+table);ids.add(r.id);for(const k of ['valor','km','km_inicial','km_final','tarifa_particular','km_base','intervalo_km','intervalo_dias','aviso_km','aviso_dias','valor_km','meta_valor_km']){if(r[k]!==undefined&&r[k]!==null&&r[k]!==''&&(!Number.isFinite(Number(r[k]))||Number(r[k])<0))throw Error('Valor numérico inválido em '+table+': '+k);}if(r.cnh_arquivo&&!(typeof r.cnh_arquivo==='string'&&/^data:application\/pdf;base64,/i.test(r.cnh_arquivo)))throw Error('PDF da CNH inválido no backup.');if(r.arquivo&&!(typeof r.arquivo==='string'&&/^data:(image\/[a-z0-9.+-]+|application\/pdf);base64,/i.test(r.arquivo)))throw Error('Comprovante inválido em '+table);}out[table]=rows;}const has=(t,id)=>out[t].some(x=>x.id===id);for(const v of out.viagens){if(!has('motoristas',v.motorista_id)||!has('veiculos',v.veiculo_id))throw Error('Há viagens sem motorista ou veículo cadastrado.');if(v.status==='Concluída'&&(+v.km_final)<(+v.km_inicial))throw Error('Há viagem com KM final menor que o inicial.');}for(const p of out.pagamentos)if(!has('viagens',p.viagem_id))throw Error('Há pagamentos sem viagem vinculada.');for(const b of out.baixas)if(!has('pendencias',b.pendencia_id))throw Error('Há baixas sem pendência vinculada.');for(const t of ['manutencoes','planos_manutencao'])for(const r of out[t])if(!has('veiculos',r.veiculo_id))throw Error('Há manutenção sem veículo cadastrado.');for(const m of out.metas_km){if(!has('motoristas',m.motorista_id)||![usageTypes[0],usageTypes[3]].includes(m.tipo_uso)||!(+m.valor_km>0))throw Error('Referência por KM inválida no backup.');}out.metas_km=normalizeDriverMetas(out.metas_km);if(raw.config?.foto&&!(typeof raw.config.foto==='string'&&/^data:image\/(jpeg|png|webp);base64,/i.test(raw.config.foto)))throw Error('Foto da empresa inválida no backup.');out.config={...out.config,...(raw.config&&typeof raw.config==='object'&&!Array.isArray(raw.config)?raw.config:{})};return out;}
function downloadBackupSnapshot(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function restoreBackupData(data){const previous=db;try{db=data;syncPaymentStatuses();const encoded=JSON.stringify(db);await saveOnline();}catch(e){db=previous;throw Error('Não foi possível restaurar. Os dados anteriores foram mantidos. O backup pode exceder o espaço disponível neste navegador.');}current=null;maintenanceCurrent=null;document.querySelector('#modal').innerHTML='';render();}
function openBackupRestore(){document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Restaurar backup</h2>${btn('Fechar','close')}</div><p>Escolha um backup JSON exportado pelo sistema. A restauração substitui os dados deste navegador pelos dados do arquivo.</p><input class="control" type="file" accept=".json,application/json" id="backup-file"><div id="backup-preview" aria-live="polite"></div></div></div>`;document.querySelector('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0],preview=document.querySelector('#backup-preview');if(!file||!preview)return;try{if(file.size>30*1024*1024)throw Error('Escolha um backup de até 30 MB.');const candidate=validateBackup(JSON.parse(await file.text()));if(!preview.isConnected)return;const labels={motoristas:'Motoristas',veiculos:'Veículos',viagens:'Viagens',receitas:'Receitas',despesas:'Despesas',pagamentos:'Pagamentos',pendencias:'Pendências',baixas:'Baixas',manutencoes:'Serviços de manutenção',planos_manutencao:'Planos periódicos',metas_km:'Metas por KM'};preview.innerHTML='<h2>Registros encontrados</h2>'+backupTables.map(t=>'<p>'+labels[t]+': <strong>'+candidate[t].length+'</strong></p>').join('')+'<p>Antes de substituir, será baixado um backup dos dados atuais. Guarde esse arquivo.</p><button type="button" class="btn" id="confirm-restore">Restaurar estes dados</button>';preview.querySelector('#confirm-restore').addEventListener('click',async()=>{if(!confirm('Substituir os dados deste navegador pelo backup selecionado?'))return;try{downloadBackupSnapshot(db,'backup_antes_restauracao_'+agoraLocal().data+'.json');await restoreBackupData(candidate);alert('Backup restaurado com sucesso.');}catch(err){alert(err.message);}});}catch(err){if(preview.isConnected)preview.textContent='Não foi possível carregar o backup: '+(err instanceof SyntaxError?'arquivo JSON inválido.':err.message);}});}


let metaEditId='';
function metasPage(){return head('Metas por KM','Cadastrar referência','meta:new')+'<section class="panel"><h2>Meta única da frota · análise do dashboard</h2>'+fleetTargetForm()+'</section>'+(db.metas_km.some(m=>db.metas_km.filter(n=>n.motorista_id===m.motorista_id&&n.tipo_uso===m.tipo_uso).length>1)?'<p class="muted">Há valores antigos diferentes para o mesmo motorista e tipo de uso. Exclua as referências excedentes e mantenha uma. Até resolver, essas combinações não sugerem valor automaticamente.</p>':'')+'<p class="muted">Metas por motorista e tipo de uso, válidas para qualquer carro. Uso particular exige meta e cobrança automática. Em viagens de trabalho, a meta é opcional e o valor pode ser alterado. Manutenção, deslocamento sem receita e uso particular sem receita não geram cobrança.</p><div class="panel">'+(newestRecords(db.metas_km,'data_cadastro').map(m=>row(name('motoristas',m.motorista_id),m.tipo_uso+' · Qualquer carro · '+entryStamp(m),money(m.valor_km)+'/km',btn('Editar','meta:edit',m.id)+btn('Excluir','meta:delete',m.id),m.tipo_uso===usageTypes[3]?'Obrigatória':'Opcional')).join('')||'<div class="empty">Nenhuma meta cadastrada. Cadastre uma meta para lançar uso particular. Viagens de trabalho podem ser registradas sem meta.</div>')+'</div>';}
function metaForm(recordId=''){if(!db.motoristas.length)return alert('Cadastre um motorista antes de definir uma referência.');metaEditId=recordId;current=null;const m=get('metas_km',recordId);document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Referência por KM</h2>${btn('Fechar','close')}</div><form id="meta-form"><div class="grid">${select('Motorista','motorista_id',opts(db.motoristas),m.motorista_id)}${select('Tipo de uso','tipo_uso',[usageTypes[0],usageTypes[3]].map(t=>[t,t]),m.tipo_uso||usageTypes[0])}${input('Valor por KM (R$)','valor_km','number',m.valor_km??'',true)}</div><p class="muted">Válida para qualquer carro. Uso particular: meta obrigatória e valor automático por KM. Trabalho: sugestão opcional e valor livre. Metas já salvas nas viagens são preservadas.</p><div class="foot">${btn('Cancelar','close')}<button type="submit" class="btn">Salvar referência</button></div></form></div></div>`;}
async function submitMeta(form){try{const v=Object.fromEntries(new FormData(form).entries());if(!get('motoristas',v.motorista_id).id)throw Error('Selecione um motorista.');delete v.veiculo_id;if(![usageTypes[0],usageTypes[3]].includes(v.tipo_uso))throw Error('Escolha um tipo de uso com receita.');if(v.valor_km===''||!Number.isFinite(+v.valor_km)||+v.valor_km<=0)throw Error('Informe um valor por KM maior que zero.');if(db.metas_km.some(m=>m.id!==metaEditId&&m.motorista_id===v.motorista_id&&m.tipo_uso===v.tipo_uso))throw Error('Já existe referência para esta combinação. Edite a existente.');v.valor_km=+v.valor_km;Object.assign(v,auditStamp(get('metas_km',metaEditId)));if(metaEditId)Object.assign(get('metas_km',metaEditId),v);else db.metas_km.push({id:id(),...v});await save();document.querySelector('#modal').innerHTML='';}catch(e){alert(e.message);}}

db.metas_km=normalizeDriverMetas(db.metas_km);
function renderBrand(){const el=document.querySelector('#app-brand');if(!el)return;const title=db.config.empresa||'Gestão de Frota Martins';const photo=db.config.foto?`<img class="brand-photo" src="${esc(db.config.foto)}" alt="Foto da empresa">`:'<b>🚚</b>';el.innerHTML=(typeof isDriver==='function'&&!isDriver()?`<button type="button" class="brand-photo-button" data-act="brand:choose" aria-label="Alterar foto ou logo" title="Alterar foto ou logo">${photo}</button>`:photo)+'<span>'+esc(title)+'</span>';document.title=title;}
async function prepareBrandPhoto(file){if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Envie uma imagem JPG, PNG ou WebP de até 10 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Não foi possível ler a foto.'));r.readAsDataURL(file);});const picture=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('A imagem não pôde ser aberta.'));img.src=data;});const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),size=Math.min(picture.naturalWidth,picture.naturalHeight);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,256,256);ctx.drawImage(picture,(picture.naturalWidth-size)/2,(picture.naturalHeight-size)/2,size,size,0,0,256,256);return canvas.toDataURL('image/jpeg',0.85);}
const brandPhotoSelections=new WeakMap();
async function previewBrandPhoto(input){
 const form=input.form,file=input.files?.[0],feedback=form.querySelector('[data-brand-feedback]'),button=form.querySelector('[type="submit"]');
 if(!file)return;
 const state={file,promise:prepareBrandPhoto(file)};brandPhotoSelections.set(form,state);
 feedback.textContent='Abrindo foto…';feedback.classList.remove('photo-error');button.disabled=true;
 try{const photo=await state.promise;if(brandPhotoSelections.get(form)!==state)return;
  const image=form.querySelector('[data-brand-preview]');image.src=photo;image.hidden=false;form.querySelector('[data-brand-placeholder]').hidden=true;
  feedback.textContent=file.name+' · Foto pronta. Clique em '+(form.id==='driver-photo-form'?'Salvar minha foto':'Salvar preferências')+'.';
 }catch(error){if(brandPhotoSelections.get(form)!==state)return;input.value='';brandPhotoSelections.delete(form);const image=form.querySelector('[data-brand-preview]');image.src=db.config.foto||'';image.hidden=!db.config.foto;form.querySelector('[data-brand-placeholder]').hidden=!!db.config.foto;feedback.textContent=error.message;feedback.classList.add('photo-error');}
 finally{if(brandPhotoSelections.get(form)===state||!brandPhotoSelections.has(form))button.disabled=false;}
}
document.addEventListener('change',e=>{if(e.target.matches('input[name="foto_empresa"]'))previewBrandPhoto(e.target);});
async function saveSettings(form){
 const previous=db.config,button=form.querySelector('[type="submit"]'),feedback=form.querySelector('[data-brand-feedback]');
 button.disabled=true;button.textContent='Salvando…';
 try{const empresa=form.elements.empresa.value.trim();if(!empresa)throw Error('Informe o nome da empresa.');
  const file=form.querySelector('[name="foto_empresa"]')?.files[0],selection=brandPhotoSelections.get(form);
  const foto=file?await(selection?.file===file?selection.promise:prepareBrandPhoto(file)):previous.foto;
  const config={...previous,empresa,alertas:form.elements.alertas.checked,exigir:form.elements.exigir.checked};if(foto)config.foto=foto;
  db.config=config;try{await saveOnline();}catch(error){db.config=previous;throw error;}
  render();notify('Preferências e foto salvas.');
 }catch(error){const message=error.message||'Não foi possível salvar. Tente novamente.',status=document.querySelector('#settings [data-brand-feedback]')||feedback;status.textContent=message;status.classList.add('photo-error');notify(message,true);}
 finally{button.disabled=false;button.textContent='Salvar preferências';}
}

function dashboardTrips(){return db.viagens.filter(v=>v.status==='Concluída'&&v.data?.startsWith(year)&&(!filterMonth||v.data.slice(5,7)===filterMonth));}
function kmPeriodLabel(){return (filterMonth?new Date(Number(year),Number(filterMonth)-1,1).toLocaleDateString('pt-BR',{month:'long'})+' de ':'Ano completo · ')+year;}
function kmVehicleName(id){const car=get('veiculos',id);return [car.modelo,car.placa].filter(Boolean).join(' · ')||'Veículo não informado';}
function kmUsageMetrics(trips){const groups=new Map();for(const trip of trips){if(trip.status!=='Concluída')continue;const key=trip.veiculo_id||'';if(!groups.has(key))groups.set(key,{veiculo_id:key,total:0,comReceita:0,semReceita:0,tipos:{}});const group=groups.get(key),km=tripKm(trip),revenue=revenueKm(trip),free=Math.max(0,km-revenue);group.total+=km;group.comReceita+=revenue;group.semReceita+=free;if(free>0||noRevenue(trip)){const kind=noRevenue(trip)?usage(trip):'Outras viagens com valor zero';group.tipos[kind]??={km:0,viagens:0};group.tipos[kind].km+=free;group.tipos[kind].viagens++;}}return [...groups.values()].map(group=>({...group,percentualSemReceita:group.total>0?group.semReceita/group.total*100:null})).sort((a,b)=>kmVehicleName(a.veiculo_id).localeCompare(kmVehicleName(b.veiculo_id),'pt-BR'));}
function kmNumber(value){return Number(value).toLocaleString('pt-BR',{maximumFractionDigits:2});}
function kmPercent(group){return group.percentualSemReceita===null?'Sem KM no período':group.percentualSemReceita.toLocaleString('pt-BR',{maximumFractionDigits:1})+'% sem receita';}
function kmUsageChart(trips){const groups=kmUsageMetrics(trips),max=Math.max(1,...groups.flatMap(group=>[group.comReceita,group.semReceita])),total=groups.reduce((sum,g)=>sum+g.total,0),free=groups.reduce((sum,g)=>sum+g.semReceita,0);return '<h2>KM com receita × KM sem receita</h2>'+`<section id="km-usage-chart" class="panel km-chart" aria-label="Quilometragem por veículo"><strong>Comparação por veículo · ${esc(kmPeriodLabel())}</strong><p class="muted km-legend"><span><i class="metric-key" style="background:var(--gold)"></i> KM com receita</span><span><i class="metric-key" style="background:#e6534e"></i> KM sem receita</span></p>${!groups.length?'<div class="empty">Nenhuma viagem concluída neste período.</div>':`<p class="muted km-totals">Total rodado: <strong>${kmNumber(total)} km</strong> · Sem receita: <strong>${kmNumber(free)} km</strong></p><div class="metric-scroll"><div class="metric-chart km-vehicle-chart" data-metric-key="KM dos veículos" style="min-width:${Math.max(310,groups.length*210)}px">${groups.map(group=>`<div class="metric-group"><div class="metric-bars" role="img" aria-label="${esc(kmVehicleName(group.veiculo_id)+': '+kmNumber(group.comReceita)+' km com receita; '+kmNumber(group.semReceita)+' km sem receita; '+kmPercent(group))}"><div class="metric-bar" style="height:${group.comReceita/max*100}%;--column-color:var(--gold)" title="${kmNumber(group.comReceita)} km com receita"><span>${kmNumber(group.comReceita)} km</span></div><div class="metric-bar" style="height:${group.semReceita/max*100}%;--column-color:#e6534e" title="${kmNumber(group.semReceita)} km sem receita"><span>${kmNumber(group.semReceita)} km</span></div></div><div class="metric-caption"><strong>${esc(kmVehicleName(group.veiculo_id))}</strong><small>Total: ${kmNumber(group.total)} km</small><b class="km-percent">${esc(kmPercent(group))}</b>${btn('Ver detalhes dos KM','km:details',group.veiculo_id)}</div></div>`).join('')}</div></div>`}<p class="muted km-note">As duas barras usam a mesma escala em KM. Considera viagens concluídas pela data de início, no período selecionado.</p></section>`;}
function kmUsageDetails(vehicleId){const group=kmUsageMetrics(dashboardTrips()).find(g=>g.veiculo_id===vehicleId);if(!group)return;current=null;const types=[usageTypes[1],usageTypes[2],usageTypes[4],...Object.keys(group.tipos).filter(type=>![usageTypes[1],usageTypes[2],usageTypes[4]].includes(type))];document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Detalhes dos KM sem receita</h2>${btn('Fechar','close')}</div><p><strong>${esc(kmVehicleName(vehicleId))}</strong><br><span class="muted">${esc(kmPeriodLabel())}</span></p><div class="km-detail-totals"><div><small>KM total</small><strong>${kmNumber(group.total)} km</strong></div><div><small>KM com receita</small><strong>${kmNumber(group.comReceita)} km</strong></div><div><small>KM sem receita</small><strong>${kmNumber(group.semReceita)} km</strong></div></div><p class="km-percent">${esc(kmPercent(group))}</p><table class="km-breakdown"><thead><tr><th>Tipo de uso</th><th>KM</th><th>Viagens</th></tr></thead><tbody>${types.map(type=>`<tr><td>${esc(type)}</td><td>${kmNumber(group.tipos[type]?.km||0)}</td><td>${group.tipos[type]?.viagens||0}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total sem receita</th><th>${kmNumber(group.semReceita)}</th><th>${Object.values(group.tipos).reduce((sum,t)=>sum+t.viagens,0)}</th></tr></tfoot></table><p class="muted km-note">Percentual sem receita = KM sem receita ÷ KM total × 100.</p><div class="foot">${btn('Fechar','close')}</div></div></div>`;}

function fleetTargetRate(){const n=Number(db.config.meta_frota_km);return Number.isFinite(n)&&n>0?n:null;}
function fleetTargetMetrics(trips,rate=fleetTargetRate()){
 const groups=new Map();for(const trip of trips){if(trip.status!=='Concluída')continue;const key=trip.veiculo_id;let g=groups.get(key);if(!g){g={veiculo_id:key,km:0,faturamento:0};groups.set(key,g);}g.km+=tripKm(trip);g.faturamento+=Number(trip.valor)||0;}
 return [...groups.values()].map(g=>({...g,meta:rate===null?null:g.km*rate,porKm:g.km>0?g.faturamento/g.km:null,atingimento:rate!==null&&g.km>0?g.faturamento/(g.km*rate)*100:null})).sort((a,b)=>kmVehicleName(a.veiculo_id).localeCompare(kmVehicleName(b.veiculo_id),'pt-BR'));
}
function fleetTargetForm(){return `<form id="fleet-target-form" class="fleet-target-form"><div class="field"><label for="fleet-target-rate">Meta única da frota · R$ por KM total</label><input id="fleet-target-rate" class="control" name="meta_frota_km" type="number" min="0.0001" step="any" placeholder="Ex.: 0,50" value="${esc(fleetTargetRate()??'')}"></div><button type="submit" class="btn">Salvar meta da frota</button><span class="muted">Deixe vazio para desativar. Apenas análise; não altera cobranças.</span></form>`;}
function fleetTargetChart(trips){const rate=fleetTargetRate(),groups=fleetTargetMetrics(trips,rate),max=Math.max(1,...groups.flatMap(g=>[g.meta||0,g.faturamento]));return '<h2>Meta por KM · Resultado por veículo</h2>'+`<section class="panel fleet-target-panel" aria-label="Meta de faturamento da frota"><strong>${esc(kmPeriodLabel())}</strong>${fleetTargetForm()}${rate===null?'<div class="empty">Cadastre uma meta única para comparar o rendimento dos veículos.</div>':!groups.length?'<div class="empty">Nenhuma viagem concluída neste período.</div>':`<p class="muted km-legend"><span><i class="metric-key" style="background:#8d8370"></i> Meta de faturamento (R$)</span><span><i class="metric-key" style="background:var(--gold)"></i> Faturamento realizado (R$)</span></p><div class="metric-scroll"><div class="metric-chart fleet-target-chart" data-metric-key="Meta da frota" style="min-width:${Math.max(310,groups.length*230)}px">${groups.map(g=>`<div class="metric-group"><div class="metric-bars" role="img" aria-label="${esc(kmVehicleName(g.veiculo_id)+': '+kmNumber(g.km)+' KM totais; meta '+money(g.meta)+'; faturamento '+money(g.faturamento))}"><div class="metric-bar" style="height:${g.meta/max*100}%;--column-color:#8d8370"><span>${money(g.meta)}</span></div><div class="metric-bar" style="height:${g.faturamento/max*100}%;--column-color:var(--gold)"><span>${money(g.faturamento)}</span></div></div><div class="metric-caption"><strong>${esc(kmVehicleName(g.veiculo_id))}</strong><small>${kmNumber(g.km)} KM totais</small><b>${g.porKm===null?'Sem KM para calcular':money(g.porKm)+'/KM'}</b><small>${g.atingimento===null?'Sem KM para comparar':kmNumber(g.atingimento)+'% da meta · '+(g.atingimento>=100?'Meta atingida':'Abaixo da meta')}</small></div></div>`).join('')}</div></div><p class="muted km-note">Meta: ${money(rate)}/KM. Inclui todos os KM das viagens concluídas, com e sem receita, pela data de início. Faturamento das viagens; não usa pagamentos nem receitas avulsas.</p>`}</section>`;}
async function saveFleetTarget(form){const button=form.querySelector('[type="submit"]'),raw=form.elements.meta_frota_km.value.trim(),rate=raw===''?null:Number(raw);if(rate!==null&&(!Number.isFinite(rate)||rate<=0)){notify('Informe uma meta por KM maior que zero ou deixe vazio para desativar.',true);return;}const previous=db.config;button.disabled=true;try{db.config={...previous};if(rate===null)delete db.config.meta_frota_km;else db.config.meta_frota_km=rate;await saveOnline();render();notify('Meta da frota salva.');}catch(e){db.config=previous;render();notify(friendly(e),true);}finally{button.disabled=false;}}
document.addEventListener('submit',e=>{if(e.target.id!=='fleet-target-form')return;e.preventDefault();if(isDriver())return;saveFleetTarget(e.target);});

// Paginação apenas de apresentação. Nunca altera os registros ou a escala dos gráficos.
const metricPageState=new Map();
function metricPageRange(total,page,size=3){const pages=Math.max(1,Math.ceil(total/size)),index=Math.max(0,Math.min(Number(page)||0,pages-1));return {page:index,pages,start:index*size,end:Math.min(total,(index+1)*size)};}
function shortMetricValue(text){const numeric=String(text).replace(/R\$|km/gi,'').replace(/\s/g,'').replace(/\./g,'').replace(',','.');const n=Number(numeric);if(!Number.isFinite(n))return text;return n>=1000000?(n/1000000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mi':n>=1000?(n/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil':n.toLocaleString('pt-BR',{maximumFractionDigits:2});}
function setupMetricPaging(){
 document.querySelectorAll('#main .metric-scroll').forEach((scroll,i)=>{
  const chart=scroll.querySelector('.metric-chart');if(!chart)return;
  const key=(chart.dataset.metricKey||String(i))+':'+year+':'+filterMonth;chart.dataset.pageKey=key;
  chart.querySelectorAll('.metric-bar>span').forEach(label=>{if(label.querySelector('.metric-label-full'))return;const full=label.textContent;label.textContent='';const a=document.createElement('span'),b=document.createElement('span');a.className='metric-label-full';a.textContent=full;b.className='metric-label-short';b.textContent=shortMetricValue(full);label.append(a,b);});
  chart.querySelectorAll('.metric-caption>strong').forEach(label=>{if(!label.textContent.includes(' · '))return;const [model,...plate]=label.textContent.split(' · ');label.textContent='';const a=document.createElement('span'),b=document.createElement('span');a.className='metric-name-main';a.textContent=model;b.className='metric-name-sub';b.textContent=plate.join(' · ');label.append(a,b);});
  const nav=document.createElement('nav');nav.className='metric-pagination';nav.setAttribute('aria-label','Navegação do gráfico '+(chart.dataset.metricKey||i));
  nav.innerHTML='<button type="button" class="mini" data-chart-step="-1" aria-label="Mostrar anteriores">‹ Anteriores</button><span class="metric-page-label" role="status" aria-live="polite"></span><button type="button" class="mini" data-chart-step="1" aria-label="Mostrar próximos">Próximos ›</button>';
  scroll.append(nav);updateMetricPage(scroll);
 });
}
function updateMetricPage(scroll,step=0){
 const chart=scroll.querySelector('.metric-chart'),groups=[...chart.querySelectorAll('.metric-group')],nav=scroll.querySelector('.metric-pagination'),mobile=window.matchMedia('(max-width:700px)').matches;
 const range=metricPageRange(groups.length,(metricPageState.get(chart.dataset.pageKey)||0)+step);metricPageState.set(chart.dataset.pageKey,range.page);
 groups.forEach((group,i)=>{group.hidden=mobile&&(i<range.start||i>=range.end);});chart.style.setProperty('--metric-visible',Math.max(1,range.end-range.start));
 nav.hidden=!mobile||groups.length<=3;nav.querySelector('[data-chart-step="-1"]').disabled=range.page===0;nav.querySelector('[data-chart-step="1"]').disabled=range.page===range.pages-1;nav.querySelector('.metric-page-label').textContent=(groups.length?range.start+1:0)+'–'+range.end+' de '+groups.length;
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-chart-step]');if(!button)return;updateMetricPage(button.closest('.metric-scroll'),Number(button.dataset.chartStep));});
window.addEventListener('resize',()=>document.querySelectorAll('#main .metric-scroll').forEach(scroll=>{if(scroll.querySelector('.metric-pagination'))updateMetricPage(scroll);}));

function passwordInput(label,name,value='',required=false){
 const target='field-'+name;
 return `<div class="field"><label for="${esc(target)}">${esc(label)}</label><div class="password-control"><input id="${esc(target)}" class="control" name="${esc(name)}" type="password" value="${esc(value)}" ${required?'required':''}><button type="button" class="password-toggle" data-password-toggle="${esc(target)}" data-password-label="${esc(label.toLowerCase())}" aria-controls="${esc(target)}" aria-pressed="false" aria-label="Mostrar ${esc(label.toLowerCase())}">Mostrar</button></div></div>`;
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-password-toggle]');if(!button)return;
 const field=document.getElementById(button.dataset.passwordToggle);if(!field)return;
 const visible=field.type==='password';field.type=visible?'text':'password';
 button.textContent=visible?'Ocultar':'Mostrar';button.setAttribute('aria-pressed',String(visible));
 button.setAttribute('aria-label',(visible?'Ocultar ':'Mostrar ')+button.dataset.passwordLabel);
});
const api=window.supabase.createClient(window.MARTINS_CONFIG.url,window.MARTINS_CONFIG.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false,storageKey:'martins-online-auth'}});
let myProfile=null,sessionUser=null,cloudSnapshot=null,recordVersions=new Map(),profiles=[],saving=false,loadingRemote=false,subscription=null;
const kinds=['motoristas','veiculos','viagens','receitas','despesas','pagamentos','pendencias','baixas','manutencoes','planos_manutencao','metas_km'];
const isDriver=()=>myProfile?.role==='motorista',clone=v=>JSON.parse(JSON.stringify(v));
function notify(message,error=false){const e=document.querySelector('#toast-status');e.textContent=message;e.className=error?'toast-error':'toast-ok';e.hidden=false;setTimeout(()=>e.hidden=true,6500);}
function statusText(s){document.querySelector('#online-status').textContent=s;}
function friendly(e){const m=e?.message||String(e||'');return m.includes('Invalid login')?'E-mail ou senha incorretos.':m.includes('Email not confirmed')?'A conta ainda não está confirmada. Fale com o administrador.':m.includes('Failed to fetch')?'Sem conexão com o servidor. O lançamento não foi confirmado.':m.includes('rate limit')?'Muitas tentativas. Aguarde alguns minutos.':m||'Não foi possível concluir.';}
async function accountCall(body){const {data:{session}}=await api.auth.getSession();if(!session)throw Error('Entre novamente.');const r=await fetch(window.MARTINS_CONFIG.url+'/functions/v1/frota-accounts',{method:'POST',headers:{'Content-Type':'application/json',apikey:window.MARTINS_CONFIG.key,Authorization:'Bearer '+session.access_token},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Não foi possível concluir.');return d;}
function authScreen(mode='login',message=''){
 document.querySelector('#application').hidden=true;const root=document.querySelector('#auth-root');root.hidden=false;
 root.innerHTML=`<div class="auth-shell"><section class="auth-card"><div class="auth-mark">M</div><p class="auth-eyebrow">GESTÃO DE FROTA MARTINS</p><h1>${mode==='password'?'Defina sua senha':'Seu trabalho, organizado.'}</h1><p class="muted">${mode==='password'?'Troque a senha temporária antes de acessar o sistema.':'Acesso individual para administrador e motoristas.'}</p><form id="online-auth-form"><div class="auth-fields">${mode!=='password'?input('E-mail','auth_email','email','',true):''}${input(mode==='password'?'Nova senha':'Senha','auth_password','password','',true)}${mode==='password'?input('Repita a nova senha','auth_confirm','password','',true):''}</div><p class="auth-error" id="auth-feedback" role="alert">${esc(message)}</p><button type="submit" class="btn auth-submit">${mode==='password'?'Salvar nova senha':'Entrar'}</button></form><p class="auth-foot">${mode==='password'?'Use 12 caracteres ou mais, com maiúscula, minúscula e número.':'Sem acesso ou esqueceu a senha? Solicite ao administrador o cadastro ou uma nova senha temporária.'}</p>${mode==='password'?'<button type="button" class="mini" id="auth-exit">Sair</button>':''}<p class="auth-private">Cada motorista acessa somente os próprios registros.</p></section></div>`;
 root.querySelector('[name="auth_password"]').autocomplete=mode==='password'?'new-password':'current-password';root.querySelector('[name="auth_password"]').minLength=mode==='password'?12:1;root.querySelector('#auth-exit')?.addEventListener('click',()=>signOut());
 root.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('[type="submit"]'),feedback=root.querySelector('#auth-feedback');b.disabled=true;feedback.textContent='';try{const f=new FormData(e.target);if(mode==='password'){if(f.get('auth_password')!==f.get('auth_confirm'))throw Error('As senhas não conferem.');const email=myProfile.email;await accountCall({action:'change_password',password:f.get('auth_password')});const {error}=await api.auth.signInWithPassword({email,password:f.get('auth_password')});if(error)throw error;}else{const {error}=await api.auth.signInWithPassword({email:String(f.get('auth_email')).trim(),password:f.get('auth_password')});if(error)throw error;}await openSession();}catch(err){feedback.textContent=friendly(err);}finally{b.disabled=false;}});
}
async function signOut(){if(saving)return notify('Aguarde o lançamento terminar.',true);if(subscription)await api.removeChannel(subscription);subscription=null;await api.auth.signOut();document.body.classList.remove('driver-mode','driver-menu-open');document.querySelector('#driver-topbar')?.remove();document.querySelector('#driver-drawer')?.remove();myProfile=null;sessionUser=null;cloudSnapshot=null;recordVersions.clear();db=blank();document.querySelector('#modal').innerHTML='';closeProof();authScreen();}
async function allRecords(){const rows=[];for(let n=0;;n+=1000){const {data,error}=await api.from('frota_records').select('*').order('kind').order('id').range(n,n+999);if(error)throw error;rows.push(...data);if(data.length<1000)break;}return rows;}
function hasOpenEditor(){return document.body.classList.contains('driver-menu-open')||!!document.querySelector('#settings')||document.activeElement?.closest?.('#fleet-target-form')||!!document.querySelector('#modal')?.innerHTML;}
async function loadOnline(force=false){if(loadingRemote||saving&&!force||!sessionUser)return;if(!force&&hasOpenEditor())return;loadingRemote=true;try{const {data:p,error:pe}=await api.from('frota_profiles').select('*').eq('user_id',sessionUser.id).single();if(pe)throw pe;myProfile=p;if(p.must_change_password){authScreen('password');return;}if(p.status!=='ativo'){pendingScreen();return;}const rows=await allRecords(),next=blank(),nextVersions=new Map();for(const row of rows){nextVersions.set(row.kind+':'+row.id,row.version);const r=clone(row.data);if(r.arquivo_path)r.arquivo='storage:'+r.arquivo_path;if(r.cnh_arquivo_path)r.cnh_arquivo='storage:'+r.cnh_arquivo_path;if(row.kind==='config')next.config={...next.config,...r};else if(next[row.kind])next[row.kind].push(r);}if(!isDriver()){const {data,error}=await api.from('frota_profiles').select('*').order('created_at',{ascending:false});if(error)throw error;profiles=data;}else profiles=[p];if(!force&&hasOpenEditor())return;recordVersions=nextVersions;db=next;cloudSnapshot=clone(db);document.querySelector('#auth-root').hidden=true;document.querySelector('#application').hidden=false;render();statusText('Online · '+(isDriver()?'Motorista':'Administrador')+' · '+myProfile.email);}catch(e){notify(friendly(e),true);statusText('Não foi possível atualizar.');throw e;}finally{loadingRemote=false;}}
function pendingScreen(){document.querySelector('#application').hidden=true;const r=document.querySelector('#auth-root');r.hidden=false;r.innerHTML=`<div class="auth-shell"><section class="auth-card"><div class="auth-mark">M</div><h1>${myProfile.status==='bloqueado'?'Acesso bloqueado':'Aguardando aprovação'}</h1><p class="muted">Fale com o administrador da frota para liberar seu acesso.</p><button type="button" class="btn" id="check-access">Verificar acesso</button> <button type="button" class="mini" id="pending-exit">Sair</button></section></div>`;r.querySelector('#check-access').onclick=()=>loadOnline(true).catch(()=>{});r.querySelector('#pending-exit').onclick=()=>signOut();}
async function openSession(){const {data:{session},error}=await api.auth.getSession();if(error)throw error;if(!session)return authScreen();sessionUser=session.user;const {data:p,error:pe}=await api.from('frota_profiles').select('*').eq('user_id',sessionUser.id).single();if(pe)throw pe;myProfile=p;if(p.must_change_password)return authScreen('password');page=isDriver()?'Minha área':'Dashboard';await loadOnline(true);if(subscription)await api.removeChannel(subscription);subscription=api.channel('frota-live-'+sessionUser.id).on('postgres_changes',{event:'*',schema:'public',table:'frota_records'},()=>loadOnline().catch(()=>{})).on('postgres_changes',{event:'*',schema:'public',table:'frota_profiles',filter:'user_id=eq.'+sessionUser.id},()=>loadOnline(true).catch(()=>{})).subscribe();}
function cleanRecord(r){const copy=clone(r);delete copy.arquivo;delete copy.cnh_arquivo;delete copy.pagamento_status;return copy;}
async function uploadFile(dataUrl,r,field){const blob=await (await fetch(dataUrl)).blob();if(blob.size>2097152||!['application/pdf','image/jpeg','image/png','image/webp'].includes(blob.type))throw Error('Use imagem ou PDF de até 2 MB.');const ext=blob.type==='application/pdf'?'pdf':blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg',path=sessionUser.id+'/'+crypto.randomUUID()+'.'+ext;const {error}=await api.storage.from('frota-documentos').upload(path,blob,{upsert:false,contentType:blob.type});if(error)throw error;r[field==='cnh_arquivo'?'cnh_arquivo_path':'arquivo_path']=path;r[field]='storage:'+path;}
async function saveOnline(){if(!myProfile||myProfile.status!=='ativo')throw Error('Acesso não liberado.');if(saving)throw Error('Aguarde o lançamento anterior.');saving=true;document.body.classList.add('saving');statusText('Salvando online…');const before=cloudSnapshot?clone(cloudSnapshot):blank();try{const changes=[];for(const kind of kinds){if(isDriver()&&kind!=='viagens')continue;const old=new Map((before[kind]||[]).map(r=>[r.id,r]));for(const r of db[kind]||[]){const prev=old.get(r.id);old.delete(r.id);if(JSON.stringify(cleanRecord(r))===JSON.stringify(prev?cleanRecord(prev):null))continue;for(const f of ['arquivo','cnh_arquivo'])if(r[f]?.startsWith('data:'))await uploadFile(r[f],r,f);changes.push({kind,id:r.id,op:'upsert',version:recordVersions.get(kind+':'+r.id)||0,data:cleanRecord(r)});}for(const id of old.keys())changes.push({kind,id,op:'delete',version:recordVersions.get(kind+':'+id)});}if(!isDriver()&&JSON.stringify(db.config)!==JSON.stringify(before.config))changes.push({kind:'config',id:'empresa',op:'upsert',version:recordVersions.get('config:empresa')||0,data:db.config});if(changes.length){const {error}=await api.rpc('frota_commit',{changes});if(error)throw error;}cloudSnapshot=clone(db);saving=false;document.body.classList.remove('saving');await loadOnline(true);}catch(e){db=before;cloudSnapshot=clone(before);saving=false;document.body.classList.remove('saving');render();statusText('Não foi salvo. Atualize e tente novamente.');throw Error(friendly(e));}finally{saving=false;document.body.classList.remove('saving');}}
const adminRender=render;render=function(){if(!myProfile)return;const admin=['Dashboard','Motoristas','Veículos','Viagens','Financeiro','Metas por KM','Manutenção','Relatórios','Acessos','Configurações'],driver=['Minha área','Viagens','Pendências','Minha conta'];menus.splice(0,menus.length,...(isDriver()?driver:admin));icons.splice(0,icons.length,...(isDriver()?['▦','↬','▤','♙']:['▦','♙','♧','↬','▤','◎','⚒','▥','♙','⚙']));if(!menus.includes(page))page=menus[0];renderBrand();if(isDriver()){nav();document.querySelector('#main').innerHTML=page==='Viagens'?trips():page==='Pendências'?driverPending():page==='Minha conta'?myAccount():driverHome();}else if(page==='Acessos'){nav();document.querySelector('#main').innerHTML=accessPage();}else adminRender();document.querySelector('#account-nav').innerHTML=`<div class="account-label">${esc(myProfile.nome||myProfile.email)}<small>${isDriver()?'Motorista':'Administrador'}</small></div><button type="button" class="nav" data-online="refresh">↻ Atualizar</button><button type="button" class="nav" data-online="password">Alterar senha</button><button type="button" class="nav" data-online="signout">Sair</button>`;if(isDriver())sanitizeDriver();document.querySelector('#mobile').insertAdjacentHTML('beforeend','<button type="button" class="nav" data-online="signout">Sair</button>');renderDriverChrome();setupMetricPaging();};
function sanitizeDriver(){document.querySelectorAll('[data-act]').forEach(b=>{const a=b.dataset.act;if(a?.startsWith('edit:')||a?.startsWith('delete:')||['paytrip','baixa','approveproof','rejectproof'].includes(a))b.remove();});}
function driverPending(){return head('Minhas pendências')+'<h2>Viagens aguardando pagamento</h2><div class="panel">'+(outstandingTrips().map(v=>row(usage(v),tripDatesLabel(v)+' · '+v.origem+' → '+v.destino,money(Math.max(0,(+v.valor||0)-paidTrip(v))),btn('Detalhes','details',v.id),payStatus(v))).join('')||'<div class="empty">Nenhuma viagem pendente.</div>')+'</div><h2>Outras pendências</h2><div class="panel">'+(newestRecords(db.pendencias).map(p=>row(p.tipo,p.descricao+' · vence em '+date(p.vencimento),money(balance(p)),'',balance(p)?'Pendente':'Quitada')).join('')||'<div class="empty">Nenhuma outra pendência.</div>')+'</div>';}
function accessPage(){return head('Acessos','Criar login do motorista','online:newlogin')+'<p class="muted">Aprovação, bloqueio e liberação são controlados somente aqui. A senha temporária deve ser entregue diretamente ao motorista.</p><div class="panel">'+(profiles.filter(p=>p.role==='motorista').map(p=>{const linked=!!p.motorista_id&&!!get('motoristas',p.motorista_id).id;const active=p.status==='ativo'&&linked;const blocked=p.status==='bloqueado';const status=blocked?'Bloqueado':active?'Ativo':'Pendente';const controls=blocked?btn('Liberar','online:block',p.user_id):active?btn('Bloquear','online:block',p.user_id):btn('Aprovar / vincular','online:approve',p.user_id);return row(p.nome||p.email,p.email+' · '+(linked?name('motoristas',p.motorista_id):'Sem cadastro vinculado'),'',controls+btn('Nova senha temporária','online:resetpassword',p.user_id),status);}).join('')||'<div class="empty">Nenhum login de motorista.</div>')+'</div>';}
function loginForm(){current=null;document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Criar login do motorista</h2>${btn('Fechar','close')}</div><form id="create-driver-login"><div class="grid">${input('Nome','nome','text','',true)}${input('E-mail de acesso','email','email','',true)}${input('Telefone','telefone','tel')}${input('Senha temporária','password','password','',true)}${select('Cadastro do motorista','motorista_id',[['','Selecione um motorista...'],['__novo__','Criar novo cadastro'],...db.motoristas.filter(m=>!profiles.some(p=>p.motorista_id===m.id)).map(m=>[m.id,m.nome])])}<label class="field wide"><span><input type="checkbox" name="approve" checked> Liberar acesso ao criar</span></label></div><p class="muted" data-driver-hint>Selecione um cadastro existente ou escolha criar novo cadastro.</p><p class="muted">Senha com 12 caracteres ou mais, maiúscula, minúscula e número. Entregue-a diretamente ao motorista.</p><div class="foot"><button type="submit" class="btn">Criar login</button></div></form></div></div>`;}
// Preenche os dados já cadastrados sem alterar a senha temporária.
function preencherLoginMotorista(form){
 const escolha=form.querySelector('[name="motorista_id"]')?.value||'';
 const motorista=escolha&&escolha!=='__novo__'?get('motoristas',escolha):null;
 const nome=form.querySelector('[name="nome"]'),email=form.querySelector('[name="email"]'),telefone=form.querySelector('[name="telefone"]');
 if(nome)nome.value=motorista?.id?(motorista.nome||''):'';
 if(email)email.value=motorista?.id?(motorista.email||''):'';
 if(telefone)telefone.value=motorista?.id?(motorista.telefone||''):'';
 const nota=form.querySelector('[data-driver-hint]');
 if(nota)nota.textContent=escolha==='__novo__'?'Novo cadastro: informe todos os dados.':motorista?.id?'Cadastro existente selecionado. Os dados faltantes podem ser preenchidos aqui; o login será vinculado a este motorista.':'Selecione um cadastro existente ou escolha criar novo cadastro.';
}
document.addEventListener('change',e=>{if(e.target.matches('#create-driver-login [name="motorista_id"]'))preencherLoginMotorista(e.target.form);});
function approveForm(uid){const p=profiles.find(p=>p.user_id===uid);if(!p)return;document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Vincular e aprovar</h2>${btn('Fechar','close')}</div><p>${esc(p.nome)} · ${esc(p.email)}</p><form id="approve-driver" data-uid="${esc(uid)}">${select('Motorista','motorista_id',[['','Selecione...'],...db.motoristas.filter(m=>!profiles.some(q=>q.user_id!==uid&&q.motorista_id===m.id)).map(m=>[m.id,m.nome])],p.motorista_id||'')}<div class="foot"><button type="submit" class="btn">Salvar e liberar</button></div></form></div></div>`;}
function resetForm(uid){document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Nova senha temporária</h2>${btn('Fechar','close')}</div><form id="reset-driver-password" data-uid="${esc(uid)}">${input('Nova senha temporária','password','password','',true)}<p class="muted">Os acessos anteriores serão encerrados. Entregue a senha diretamente ao motorista.</p><div class="foot"><button type="submit" class="btn">Redefinir senha</button></div></form></div></div>`;}
const originalAction=action;action=async function(a,i){try{if(isDriver()&&!(a?.startsWith('proof:')||a==='cnh:show'||['theme','close','new:viagens','finish','details','attachproof'].includes(a)))throw Error('Área restrita ao administrador.');if(a==='online:newlogin')return loginForm();if(a==='online:approve')return approveForm(i);if(a==='online:resetpassword')return resetForm(i);if(a==='online:block'){const p=profiles.find(p=>p.user_id===i);if(!p)return;if(p.status==='bloqueado'&&(!p.motorista_id||!get('motoristas',p.motorista_id).id))throw Error('Vincule um cadastro de motorista antes de liberar o acesso.');if(!confirm(p.status==='bloqueado'?'Liberar o motorista?':'Bloquear o acesso do motorista?'))return;const {error}=await api.from('frota_profiles').update({status:p.status==='bloqueado'?'ativo':'bloqueado'}).eq('user_id',i);if(error)throw error;await loadOnline(true);return;}if(a==='export')return await exportOnlineBackup();if(a==='reset')throw Error('Limpeza total desativada na versão online. Exclua os registros individualmente.');await originalAction(a,i);if(isDriver()){sanitizeDriver();if(a==='finish'){const t=document.querySelector('#form [name="tipo_uso"]');if(t)t.disabled=true;}if(a==='new:viagens'){const f=document.querySelector('#form'),sel=f?.querySelector('[name="motorista_id"]');if(sel){sel.value=myProfile.motorista_id;sel.closest('.field').hidden=true;}updateUsageForm(f,true);}}}catch(e){notify(friendly(e),true);}};
const originalShowProof=showProof;showProof=async function(table,rid,kind='proof'){const r=get(table,rid),field=kind==='cnh'?'cnh_arquivo':'arquivo',path=kind==='cnh'?r.cnh_arquivo_path:r.arquivo_path;if(!path)return originalShowProof(table,rid,kind);try{notify('Abrindo documento…');const {data,error}=await api.storage.from('frota-documentos').download(path);if(error)throw error;const url=await blobUrl(data),old=r[field];r[field]=url;try{originalShowProof(table,rid,kind);}finally{r[field]=old;}}catch(e){notify(friendly(e),true);}};
function blobUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});}
async function exportOnlineBackup(){if(isDriver())throw Error('Somente administrador exporta backup.');notify('Preparando backup com anexos…');const snapshot=clone(db);for(const k of kinds)for(const r of snapshot[k])for(const field of ['arquivo','cnh_arquivo']){const key=field==='arquivo'?'arquivo_path':'cnh_arquivo_path';if(!r[key])continue;const {data,error}=await api.storage.from('frota-documentos').download(r[key]);if(error)throw error;r[field]=await blobUrl(data);delete r[key];}downloadBackupSnapshot(snapshot,'Gestao_Frota_Martins_backup_'+agoraLocal().data+'.json');notify('Backup pronto. Confira Downloads.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-online]');if(!b)return;try{if(b.dataset.online==='signout')await signOut();if(b.dataset.online==='refresh')await loadOnline(true);if(b.dataset.online==='password')authScreen('password');}catch(err){notify(friendly(err),true);}});
document.addEventListener('submit',async e=>{if(!['create-driver-login','approve-driver','reset-driver-password'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('[type="submit"]');b.disabled=true;try{const v=Object.fromEntries(new FormData(f).entries());if(f.id==='create-driver-login'){
 if(!v.motorista_id)throw Error('Selecione um motorista cadastrado ou escolha Criar novo cadastro.');
 if(v.motorista_id==='__novo__')v.motorista_id='';
 else{
  const motorista=get('motoristas',v.motorista_id);
  if(!motorista.id)throw Error('Cadastro do motorista não encontrado.');
  if(profiles.some(p=>p.motorista_id===motorista.id))throw Error('Este motorista já possui login vinculado. Use Vincular / aprovar.');
  if(!v.nome?.trim())v.nome=motorista.nome||'';
  if(!v.email?.trim())v.email=motorista.email||'';
  if(!v.telefone?.trim())v.telefone=motorista.telefone||'';
 }
 await accountCall({action:'create_driver',...v,approve:!!v.approve});
 }if(f.id==='reset-driver-password')await accountCall({action:'reset_password',user_id:f.dataset.uid,password:v.password});if(f.id==='approve-driver'){if(!get('motoristas',v.motorista_id).id)throw Error('Selecione o motorista.');const {error}=await api.from('frota_profiles').update({motorista_id:v.motorista_id,status:'ativo'}).eq('user_id',f.dataset.uid);if(error)throw error;}document.querySelector('#modal').innerHTML='';await loadOnline(true);notify('Acesso atualizado.');}catch(err){notify(friendly(err),true);}finally{b.disabled=false;}});
window.addEventListener('online',()=>loadOnline().catch(()=>{}));window.addEventListener('offline',()=>statusText('Sem conexão · é necessário internet para salvar'));window.addEventListener('focus',()=>{setTimeout(()=>loadOnline().catch(()=>{}),350);});window.addEventListener('unhandledrejection',e=>{e.preventDefault();notify(friendly(e.reason),true);});
const driverIconPaths={menu:'M4 6h16M4 12h16M4 18h16',home:'m3 10 9-7 9 7v10H15v-6H9v6H3Z',route:'M6 4a3 3 0 1 0 0 .01M18 14a3 3 0 1 0 0 .01M6 8v3a3 3 0 0 0 3 3h6a3 3 0 0 1 3 3v3',km:'M4 5h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Zm3 4v6m5-6v6m5-6v6',pending:'M9 4H5v17h14V4h-4M9 2h6v4H9Zm-1 9 1 1 2-2m2 1h3m-8 5 1 1 2-2m2 1h3',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2Z',car:'m5 8 2-5h10l2 5M3 10a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v8H3Zm3 4h1m10 0h1M5 18v3m14-3v3',camera:'M3 6h4l2-3h6l2 3h4v14H3Zm13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M4.2 4.2 2.8 2.8m18.4 18.4-1.4-1.4M4.2 19.8l-1.4 1.4M21.2 2.8l-1.4 1.4M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',plus:'M12 4v16M4 12h16',chevron:'m9 5 7 7-7 7',close:'m5 5 14 14M5 19 19 5'};
function driverIcon(name){return `<svg class="driver-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${driverIconPaths[name]||driverIconPaths.user}"/></svg>`;}
function driverAvatar(){return myProfile.foto_perfil?`<img src="${esc(myProfile.foto_perfil)}" alt="Sua foto de perfil">`:`<svg class="driver-avatar-placeholder" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="49" fill="#d0c6b3"/><path d="M19 98v-9a31 31 0 0 1 62 0v9" fill="#716651"/><circle cx="50" cy="38" r="20" fill="#716651"/></svg>`;}
function driverIdentity(){const d=get('motoristas',myProfile.motorista_id),driverName=d.nome||myProfile.nome||'Motorista';return `<section class="driver-profile" aria-label="Seu perfil"><button type="button" class="driver-avatar-button" data-online="avatar" aria-label="Alterar minha foto de perfil">${driverAvatar()}<span class="driver-camera">${driverIcon('camera')}</span></button><div class="driver-identity"><p>ÁREA DO MOTORISTA</p><h1>${esc(driverName)}</h1><span class="driver-role">Motorista</span><span class="driver-connection"><i></i><span data-driver-connection>${navigator.onLine===false?'Sem conexão':'Online'}</span></span></div></section>`;}
function driverHome(){const done=db.viagens.filter(v=>v.status==='Concluída'),due=db.pendencias.reduce((s,p)=>s+balance(p),0)+outstandingTrips().reduce((s,v)=>s+Math.max(0,(+v.valor||0)-paidTrip(v)),0),km=done.reduce((s,v)=>s+tripKm(v),0),active=newestTrips(db.viagens.filter(v=>v.status==='Em andamento'));
 return `<div class="driver-home">${driverIdentity()}<button type="button" class="driver-start" data-act="new:viagens">${driverIcon('plus')}<span>Registrar viagem do dia</span></button><div class="driver-stats"><section class="driver-stat">${driverIcon('route')}<div><span>Viagens<br>concluídas</span><strong>${done.length}</strong></div></section><section class="driver-stat">${driverIcon('km')}<div><span>KM<br>registrados</span><strong>${km.toLocaleString('pt-BR')} <small>km</small></strong></div></section></div><button type="button" class="driver-due" data-page="Pendências">${driverIcon('pending')}<span class="driver-due-value"><span>Suas pendências</span><strong>${money(due)}</strong></span><span class="driver-due-link">Ver detalhes ${driverIcon('chevron')}</span></button><h2 class="driver-section-title">Em andamento</h2>${active.length?'<div class="panel driver-active">'+active.map(v=>row(tripVehicleLabel(v),usage(v)+' · '+date(v.data)+(v.hora?' às '+v.hora:'')+' · '+v.origem+' → '+v.destino,'',btn('Concluir viagem','finish',v.id,'btn'),'Em andamento')).join('')+'</div>':`<div class="driver-empty">${driverIcon('car')}<p>Nenhuma viagem em andamento</p></div>`}</div>`;
}
function myAccount(){const d=get('motoristas',myProfile.motorista_id);return '<div class="driver-home">'+driverIdentity()+`<section class="panel"><h2>Minha conta</h2><p>${esc(myProfile.email)}</p><p>${esc(d.telefone||'')}</p><p>CNH: ${esc(d.cnh_numero||'Não informada')} · Validade: ${esc(date(d.cnh_validade))}</p>${d.cnh_arquivo?btn('Ver CNH','cnh:show',d.id):''}<p class="muted">Solicite alterações cadastrais ao administrador.</p><button type="button" class="mini" data-online="avatar">Alterar foto de perfil</button> <button type="button" class="mini" data-online="password">Alterar senha</button></section><h2>Metas por KM</h2><section class="panel">${db.metas_km.map(m=>row(m.tipo_uso,'Qualquer veículo',money(m.valor_km)+'/km')).join('')||'<p class="muted">Solicite ao administrador a meta para uso particular.</p>'}</section></div>`;}
function renderDriverChrome(){const driver=isDriver();document.body.classList.toggle('driver-mode',driver);document.body.classList.remove('driver-menu-open');let header=document.querySelector('#driver-topbar'),drawer=document.querySelector('#driver-drawer');
 if(!driver){header?.remove();drawer?.remove();return;}
 if(!header){header=document.createElement('header');header.id='driver-topbar';header.className='driver-topbar';document.querySelector('#application').prepend(header);}
 const title=db.config.empresa||'Gestão de Frota Martins';header.innerHTML=`<button type="button" class="driver-header-button" data-online="menu" aria-label="Abrir menu" aria-expanded="false">${driverIcon('menu')}</button><div class="driver-brand"><span class="driver-brand-mark">${db.config.foto?`<img src="${esc(db.config.foto)}" alt="Logo da empresa">`:'M'}</span><span>${title==='Gestão de Frota Martins'?'Gestão de Frota<strong>Martins</strong>':esc(title)}</span></div><button type="button" class="driver-header-button driver-theme" data-act="theme" aria-label="${theme==='dark'?'Ativar tema claro':'Ativar tema escuro'}">${driverIcon('sun')}</button>`;
 const items=[['Minha área','home'],['Viagens','route'],['Pendências','pending'],['Minha conta','user']];document.querySelector('#mobile').innerHTML=items.map(([label,icon])=>`<button type="button" class="driver-bottom-item ${page===label?'active':''}" data-page="${label}" ${page===label?'aria-current="page"':''}>${driverIcon(icon)}<span>${label}</span></button>`).join('');
 if(!drawer){drawer=document.createElement('div');drawer.id='driver-drawer';drawer.hidden=true;document.querySelector('#application').append(drawer);}
 drawer.innerHTML=`<button type="button" class="driver-drawer-shade" data-online="closemenu" aria-label="Fechar menu"></button><section class="driver-drawer-panel" role="dialog" aria-modal="true" aria-label="Menu do motorista"><div class="head"><strong>Menu do motorista</strong><button type="button" class="driver-header-button" data-online="closemenu" aria-label="Fechar menu">${driverIcon('close')}</button></div>${items.map(([label,icon])=>`<button type="button" class="nav ${page===label?'active':''}" data-page="${label}">${driverIcon(icon)} ${label}</button>`).join('')}<hr><button type="button" class="nav" data-online="refresh">Atualizar dados</button><button type="button" class="nav" data-online="signout">Sair da conta</button></section>`;drawer.hidden=true;updateDriverConnection();
}
function updateDriverConnection(){const offline=navigator.onLine===false;document.body.classList.toggle('connection-offline',offline);document.querySelectorAll('[data-driver-connection]').forEach(n=>n.textContent=offline?'Sem conexão':'Online');}
function driverPhotoForm(){current=null;document.querySelector('#modal').innerHTML=`<div class="overlay"><div class="modal"><div class="head"><h2>Minha foto de perfil</h2>${btn('Fechar','close')}</div><form id="driver-photo-form"><div class="field"><label for="driver-photo-file">Escolha sua foto</label><label class="brand-photo-preview driver-photo-preview" for="driver-photo-file"><img data-brand-preview src="${esc(myProfile.foto_perfil||'')}" alt="Prévia da sua foto" ${myProfile.foto_perfil?'':'hidden'}><span data-brand-placeholder ${myProfile.foto_perfil?'hidden':''}>Escolher foto</span></label><input id="driver-photo-file" class="control brand-photo-file" type="file" name="foto_empresa" accept="image/jpeg,image/png,image/webp"><p class="muted">JPG, PNG ou WebP de até 10 MB. Confira a prévia antes de salvar.</p><p class="muted photo-feedback" data-brand-feedback role="status" aria-live="polite"></p></div><div class="foot">${btn('Cancelar','close')}<button type="submit" class="btn">Salvar minha foto</button></div></form></div></div>`;}
document.addEventListener('click',e=>{const button=e.target.closest('[data-online]');if(!button||!isDriver())return;const action=button.dataset.online;if(action==='avatar')driverPhotoForm();if(action==='menu'){const drawer=document.querySelector('#driver-drawer');drawer.hidden=false;document.body.classList.add('driver-menu-open');button.setAttribute('aria-expanded','true');drawer.querySelector('.driver-drawer-panel [data-online="closemenu"]').focus();}if(action==='closemenu'){document.querySelector('#driver-drawer').hidden=true;document.body.classList.remove('driver-menu-open');const menu=document.querySelector('[data-online="menu"]');menu.setAttribute('aria-expanded','false');menu.focus();}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.body.classList.contains('driver-menu-open')){const buttons=[...document.querySelectorAll('.driver-drawer-panel button')],first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&document.body.classList.contains('driver-menu-open'))document.querySelector('#driver-drawer .driver-drawer-shade')?.click();});
document.addEventListener('submit',async e=>{if(e.target.id!=='driver-photo-form')return;e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]'),feedback=form.querySelector('[data-brand-feedback]');button.disabled=true;button.textContent='Salvando…';try{if(!isDriver())throw Error('Use o acesso do motorista.');const file=form.querySelector('input[type="file"]').files[0];if(!file)throw Error('Escolha uma foto antes de salvar.');const selection=brandPhotoSelections.get(form),photo=await(selection?.file===file?selection.promise:prepareBrandPhoto(file));const {error}=await api.rpc('frota_set_avatar',{photo});if(error)throw error;myProfile.foto_perfil=photo;document.querySelector('#modal').innerHTML='';render();await loadOnline(true);notify('Sua foto de perfil foi salva.');}catch(error){feedback.textContent=friendly(error);feedback.classList.add('photo-error');}finally{button.disabled=false;button.textContent='Salvar minha foto';}});
window.addEventListener('online',updateDriverConnection);window.addEventListener('offline',updateDriverConnection);

authScreen();openSession().catch(e=>authScreen('login',friendly(e)));
